const caProvinceNameToCode = {
  ALBERTA:'AB', 'BRITISH COLUMBIA':'BC', MANITOBA:'MB', 'NEW BRUNSWICK':'NB', NEWFOUNDLAND:'NL',
  'NEWFOUNDLAND AND LABRADOR':'NL', 'NOVA SCOTIA':'NS', 'NORTHWEST TERRITORIES':'NT', NUNAVUT:'NU',
  ONTARIO:'ON', 'PRINCE EDWARD ISLAND':'PE', QUEBEC:'QC', SASKATCHEWAN:'SK', YUKON:'YT'
};

function norm(v) {
  return String(v || '').trim();
}

function normState(v) {
  return norm(v).toUpperCase().replace(/\./g, '').replace(/\s+/g, ' ');
}

function normCountry(v) {
  return norm(v).toUpperCase().replace(/\./g, '').replace(/\s+/g, ' ');
}

function resolveContactTimezone(c) {
  const explicitTz = norm(c.contact_timezone) || norm(c.timezone);
  if (explicitTz && isValidTimeZone(explicitTz)) return explicitTz;

  const stateNorm = normState(norm(c.state) || norm(c.company_state));
  const countryNorm = normCountry(norm(c.country) || norm(c.company_country));

  const usCodes = new Set(['US', 'USA', 'UNITED STATES', 'UNITED STATES OF AMERICA']);
  const caCodes = new Set(['CA', 'CAN', 'CANADA']);

  let stateCode = stateNorm;
  if (stateCode.length > 2) {
    stateCode = usStateNameToCode[stateCode] || caProvinceNameToCode[stateCode] || stateCode;
  }

  if (!countryNorm || usCodes.has(countryNorm)) {
    if (usStateToTz[stateCode]) return usStateToTz[stateCode];
  }

  if (caCodes.has(countryNorm)) {
    if (caProvinceToTz[stateCode]) return caProvinceToTz[stateCode];
  }

  if (usStateToTz[stateCode]) return usStateToTz[stateCode];
  if (caProvinceToTz[stateCode]) return caProvinceToTz[stateCode];

  return '';
}

let senderFieldId = '';
if (!dryRun) {
  const cf = await apiRequest.call(this, 'GET', `/locations/${locationId}/customFields?model=contact`);
  if (!cf.ok) throw new Error(`Failed custom fields lookup: ${JSON.stringify(cf.data)}`);
  const arr = Array.isArray(cf.data?.customFields)
    ? cf.data.customFields
    : Array.isArray(cf.data?.data?.customFields)
      ? cf.data.data.customFields
      : Array.isArray(cf.data?.data)
        ? cf.data.data
        : [];
  senderFieldId = arr.find((f) => String(f?.name || '').trim() === senderFieldName)?.id || '';
  if (!senderFieldId) throw new Error(`Missing GHL field: ${senderFieldName}`);
}

const runId = `${new Date().toISOString()}__sender_release`;
const out = [];

if (!withinDispatchWindow) {
  out.push({
    json: {
      status: 'summary',
      summary: {
        ok: true,
        dryRun,
        runId,
        warmupWeek,
        windowOpen: false,
        windowLabel: 'Mon-Sat, 8:00 AM ET to 5:00 PM PT',
        sundayBlocked: isSundayEt,
        currentEtHour: etHour,
        currentPtHour: ptHour,
        candidates: 0,
        totalUnreleased: backlogTotal,
        backlogBeyondBatch: backlogTotal,
        planned: 0,
        queued: 0,
        deferred: 0,
        deferredOutsideBusinessHours: 0,
        deferredMissingTimezone: 0,
        errors: 0,
        warnings: [isSundayEt ? 'SUNDAY_BLOCKED: no dispatch on Sundays.' : 'DISPATCH_WINDOW_CLOSED: no contacts dispatched outside Mon-Sat 8:00 AM ET to 5:00 PM PT.'],
        senders: senders.map((s) => ({
          email: s.email,
          cap: s.cap,
          inFlightDueToday: s.inFlightDueToday,
          safetyBuffer: s.safetyBuffer,
          remainingAfterPlan: s.remaining,
        })),
      },
    },
  });
  return out;
}

for (const c of candidates) {
  const rowId = Number(c.apollo_row_id || 0);
  const email = String(c.email || '').trim();

  if (!email) {
    out.push({ json: { status: 'skipped_missing_email', apollo_row_id: c.apollo_row_id } });
    continue;
  }

  const contactTz = resolveContactTimezone(c);
  if (!contactTz) {
    out.push({ json: { status: 'deferred_missing_timezone', apollo_row_id: rowId || null, email } });
    continue;
  }

  const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: contactTz }));
  const localHour = localNow.getHours();
  if (localHour < 8 || localHour >= 17) {
    out.push({ json: { status: 'deferred_outside_business_hours', apollo_row_id: rowId || null, email, timezone: contactTz, localHour } });
    continue;
  }

  const sender = pickSenderForCandidate(rowId || hashString(email));
  if (!sender) {
    out.push({ json: { status: 'deferred_no_capacity', apollo_row_id: c.apollo_row_id, email } });
    continue;
  }

  if (dryRun) {
    out.push({
      json: {
        status: 'planned',
        apollo_row_id: c.apollo_row_id,
        email,
        sender_email: sender,
        timezone: contactTz,
        run_id: runId,
      },
    });
    continue;
  }

  let contactId = '';
  let contactSource = '';

  const dup = await apiRequest.call(
    this,
    'GET',
    `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&email=${encodeURIComponent(email)}`,
  );

  if (dup.ok && dup.data?.contact?.id) {
    contactId = String(dup.data.contact.id);
    contactSource = 'existing';
  }

  if (!contactId) {
    await sleep(200);
    const upsert = await apiRequest.call(this, 'POST', '/contacts/upsert', {
      locationId,
      email,
      firstName: c.first_name || undefined,
      lastName: c.last_name || undefined,
      phone: c.phone || undefined,
      companyName: c.company_name || undefined,
    });
    if (!upsert.ok) {
      out.push({ json: { status: 'error_upsert', apollo_row_id: rowId || null, email, sender_email: sender, details: upsert.data } });
      continue;
    }
    contactId = String(upsert.data?.contact?.id || upsert.data?.id || upsert.data?.contactId || '');
    contactSource = 'upsert';
  }

  if (!contactId) {
    out.push({ json: { status: 'error_contact_id', apollo_row_id: rowId || null, email, sender_email: sender, details: dup.data } });
    continue;
  }

  const setField = await apiRequest.call(this, 'PUT', `/contacts/${contactId}`, {
    customFields: [{ id: senderFieldId, value: sender }],
  });

  if (!setField.ok) {
    out.push({ json: { status: 'error_set_sender', apollo_row_id: rowId || null, email, sender_email: sender, contact_id: contactId, details: setField.data } });
    continue;
  }

  const tag = await apiRequest.call(this, 'POST', `/contacts/${contactId}/tags`, { tags: [queueTag] });
  if (!tag.ok) {
    out.push({ json: { status: 'error_add_queue_tag', apollo_row_id: rowId || null, email, sender_email: sender, contact_id: contactId, details: tag.data } });
    continue;
  }

  out.push({
    json: {
      status: 'queued',
      apollo_row_id: rowId || null,
      email,
      sender_email: sender,
      contact_id: contactId,
      contact_source: contactSource,
      timezone: contactTz,
      run_id: runId,
    },
  });
}

const warnings = [];
if (dryRun) warnings.push('DRY_RUN_ACTIVE: no GHL writes or release log inserts are executed.');
if (!apiKey) warnings.push('GHL_API_KEY_EMPTY: apiKey is blank in Config/env.');
warnings.push('Deferred contacts are retried automatically on next run because they are not inserted into release log.');

out.push({
  json: {
    status: 'summary',
    summary: {
      ok: true,
      dryRun,
      runId,
      warmupWeek,
      windowOpen: true,
      windowLabel: 'Mon-Sat, 8:00 AM ET to 5:00 PM PT',
      sundayBlocked: isSundayEt,
      currentEtHour: etHour,
      currentPtHour: ptHour,
      candidates: candidates.length,
      totalUnreleased: backlogTotal,
      backlogBeyondBatch: Math.max(0, backlogTotal - candidates.length),
      planned: out.filter((x) => x.json.status === 'planned').length,
      queued: out.filter((x) => x.json.status === 'queued').length,
      deferred: out.filter((x) => String(x.json.status || '').startsWith('deferred_')).length,
      deferredOutsideBusinessHours: out.filter((x) => x.json.status === 'deferred_outside_business_hours').length,
      deferredMissingTimezone: out.filter((x) => x.json.status === 'deferred_missing_timezone').length,
      errors: out.filter((x) => String(x.json.status || '').startsWith('error_')).length,
      warnings,
      senders: senders.map((s) => ({
        email: s.email,
        cap: s.cap,
        inFlightDueToday: s.inFlightDueToday,
        safetyBuffer: s.safetyBuffer,
        remainingAfterPlan: s.remaining,
      })),
    },
  },
});

return out;

const rows = $items('Dispatch + Queue (DryRun Safe)').map((i) => i.json || {});
const summary = rows.find((r) => r.status === 'summary') || null;
const sample = rows.filter((r) => r.status !== 'summary').slice(0, 20);
return [{ json: { ok: true, summary: summary?.summary || null, sample } }];
